{
  "claims": [
    {
      "claim": "Conditional distribution of $X$ given $Y$ is defined as $P(X|Y) = \\frac{P(X,Y)}{P(Y)}$",
      "supported": true,
      "evidence_or_problem": "Source: [00:03:35\u201300:04:12] 'the conditional distribution on X given Y by definition is simply the ratio of joint distribution over the distribution of a condition. Or in conceptual terms, it can be written as conditional equals joint over marginal.'"
    },
    {
      "claim": "If $X$ and $Y$ are independent, then $P(X|Y) = P(X)$",
      "supported": true,
      "evidence_or_problem": "Source: [00:04:13\u201300:05:01] 'if we assume that X and Y are completely independent of one another... if we divide it over P of y, we get P of x.'"
    },
    {
      "claim": "Independence implies that $Y$ contains no information about $X$",
      "supported": true,
      "evidence_or_problem": "Source: [00:04:13\u201300:05:01] 'this means that y contains no information about x.'"
    },
    {
      "claim": "When $X$ and $Y$ are dependent, observing $Y$ changes the distribution of $X$",
      "supported": true,
      "evidence_or_problem": "Source: [00:04:13\u201300:05:01] 'in the opposite case, when x and y are dependent, then the observation of y somehow changes the distribution of x.'"
    },
    {
      "claim": "The definition of conditional probability applies to continuous random variables",
      "supported": false,
      "evidence_or_problem": "Source: [00:03:04\u201300:03:35] mentions 'does it actually matter?' regarding whether $X$ and $Y$ are continuous, indicating uncertainty about applicability to discrete variables."
    },
    {
      "claim": "The conditional distribution of $X$ given $Y$ is the same as the marginal distribution of $X$ when $X$ and $Y$ are independent",
      "supported": true,
      "evidence_or_problem": "Source: [00:04:13\u201300:05:01] 'if we divide it over P of y, we get P of x.'"
    },
    {
      "claim": "The ASR ends with an incomplete thought about the dependent case",
      "supported": true,
      "evidence_or_problem": "Source: [00:05:01\u201300:05:31] ends with 'it can be shown, and this is' without completing the thought."
    },
    {
      "claim": "The conditional distribution of $X$ given $Y$ changes when $X$ and $Y$ are dependent",
      "supported": true,
      "evidence_or_problem": "Source: [00:04:13\u201300:05:01] 'in the opposite case, when x and y are dependent, then the observation of y somehow changes the distribution of x.'"
    }
  ],
  "clarity_1_to_5": 4,
  "caveat": "The ASR mentions uncertainty about whether the definition applies to discrete variables (the speaker questions if continuity matters), but the notes indicate the definition may apply to both continuous and discrete variables. The ASR ends with an incomplete thought about the dependent case."
}
